// Encaje del SVG provincial en el lienzo 1000×380 del renderizador y
// proyección Mercator lon/lat → lienzo, coherente con el geoViewBox.
const CMAP = (() => {
  const MW = 1000, MH = 380, PAD = 26;
  const k = (MW - PAD * 2) / CUBA_GEOBOX.sw;
  return { MW, MH, k, tx: PAD, ty: (MH - CUBA_GEOBOX.sh * k) / 2 };
})();
const mercY = (lat) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
function cubaProject([lon, lat]) {
  const { w, n, e, s: sur, sw, sh } = CUBA_GEOBOX;
  const x = ((lon - w) / (e - w)) * sw;
  const y = ((mercY(n) - mercY(lat)) / (mercY(n) - mercY(sur))) * sh;
  return [CMAP.tx + x * CMAP.k, CMAP.ty + y * CMAP.k];
}

